	if err := os.WriteFile(verdict, []byte(`{"issue": 12, "outcome": "keep",
		"premise": {"verdict": "no-claims", "claims": []},
		"fit": {"applies": true, "reason": "in scope"},
		"built": {"built": false, "evidence": ""}, "duplicates": []}`), 0o644); err != nil {
		t.Fatal(err)
	}
	for _, tt := range []struct {
