package review

import (
	"errors"
	"fmt"
	"net/http"

	"github.com/partio-io/cli/internal/github"
)

// Config is one gate run for one reviewed issue.
type Config struct {
	VerdictPath string
	Repo        string // owner/name
	Issue       int    // the reviewed issue
	Night       string // UTC date, YYYY-MM-DD, that names the night comment
	DryRun      bool   // record only; change nothing on the reviewed issue
	APIBaseURL  string
	Token       string
	HTTPClient  *http.Client // nil means http.DefaultClient
}

// Result is what the gate found in the verdict file.
type Result struct {
	Valid   bool
	Outcome string // the verdict outcome when Valid
	Cause   string // why there is no verdict when not Valid
}

func (c Config) client() github.Client {
	return github.Client{BaseURL: c.APIBaseURL, Token: c.Token, HTTPClient: c.HTTPClient}
}

// Run loads the verdict for cfg.Issue, acts on the reviewed issue, and
// records the verdict as one row in the tracking issue. A missing or
// invalid verdict, or a rewrite whose new text fails a shape check, is
// "no verdict": Run records that row with its cause and returns a
// Result that is not Valid, with a nil error. A non-nil error means the
// gate could not talk to GitHub. In dry-run mode Run reads the reviewed
// issue and changes nothing on it, and the row of a rewrite that fails
// a shape check also carries the proposed text. Outside dry-run a
// verdict the gate cannot act on is no verdict: a closed issue, a pull
// request, or a duplicate close whose kept issue is not open.
func Run(cfg Config) (Result, error) {
	gh := cfg.client()
	issue, err := gh.GetIssue(cfg.Repo, cfg.Issue)
	if err != nil {
		return Result{}, fmt.Errorf("read issue #%d: %w", cfg.Issue, err)
	}

	res := Result{}
	v, err := LoadVerdict(cfg.VerdictPath, cfg.Issue)
	badShape := false
	if err == nil && v.Outcome == OutcomeRewrite {
		err = checkShape(issue.Body, *v.Rewrite)
		badShape = err != nil
	}
	var kept *github.Issue
	if err == nil && !cfg.DryRun {
		kept, err = actable(gh, cfg.Repo, issue, v)
		var no refusal
		if err != nil && !errors.As(err, &no) {
			return Result{}, err
		}
	}
	var r string
	if err != nil {
		res.Cause = err.Error()
		r = noVerdictRow(issue, res.Cause)
		if badShape && cfg.DryRun {
			r += indent(rewriteDetails(*v.Rewrite))
		}
	} else {
		res.Valid, res.Outcome = true, v.Outcome
		r = row(issue, v, cfg.DryRun)
	}
	if res.Valid && !cfg.DryRun {
		if err := act(gh, cfg.Repo, issue, v, kept); err != nil {
			return Result{}, err
		}
	}

	tracking, err := findOrCreateTracking(gh, cfg.Repo)
	if err != nil {
		return Result{}, err
	}
	nights, err := appendRow(gh, cfg.Repo, tracking.Number, cfg.Night, r)
	if err != nil {
		return Result{}, err
	}
	if err := writeSummary(gh, cfg.Repo, tracking, nights); err != nil {
		return Result{}, err
	}
	return res, nil
}
package review

import (
	"fmt"
	"strings"

	"github.com/partio-io/cli/internal/github"
)

// row is one tracking line for a valid verdict: number, title, verdict,
// reason and link. A rewrite carries its full proposed text in a
// collapsed section, indented so it stays under its row, with the body
// fenced so its own markup cannot close the section or hide later rows.
func row(issue github.Issue, v Verdict, dryRun bool) string {
	verdict := "**" + v.Outcome + "**"
	if dryRun {
		verdict += " (dry run)"
	}
	line := fmt.Sprintf("- #%d · %s · %s · %s · [link](%s)\n",
		issue.Number, oneLine(issue.Title), verdict, reason(v), issue.HTMLURL)
	if v.Outcome != OutcomeRewrite {
		return line
	}
	return line + indent(rewriteDetails(*v.Rewrite))
}

// noVerdictRow is the tracking line for a missing or invalid verdict.
func noVerdictRow(issue github.Issue, cause string) string {
	return fmt.Sprintf("- #%d · %s · **no verdict** · %s · [link](%s)\n",
		issue.Number, oneLine(issue.Title), oneLine(cause), issue.HTMLURL)
}

func reason(v Verdict) string {
	switch {
	case v.Outcome == OutcomeClose && v.CloseReason == ReasonDuplicate:
		return fmt.Sprintf("duplicate of #%d", v.DuplicateOf)
	case v.Outcome == OutcomeClose:
		return v.CloseReason
	case v.Outcome == OutcomeRewrite && len(v.Rewrite.Changes) > 0:
		return oneLine(strings.Join(v.Rewrite.Changes, "; "))
	}
	return oneLine(v.Fit.Reason)
}

func rewriteDetails(rw Rewrite) string {
	var b strings.Builder
	b.WriteString("\n<details><summary>Proposed rewrite</summary>\n\n")
	fmt.Fprintf(&b, "**Title:** %s\n\n", oneLine(rw.Title))
	fence := fenceFor(rw.Body)
	b.WriteString(fence + "markdown\n")
	b.WriteString(strings.TrimRight(rw.Body, "\n"))
	b.WriteString("\n" + fence + "\n\n</details>\n\n")
	return b.String()
}

// fenceFor returns a backtick fence longer than any backtick run in
// text, so text cannot close it.
func fenceFor(text string) string {
	longest, run := 0, 0
	for _, r := range text {
		if r == '`' {
			run++
			longest = max(longest, run)
		} else {
			run = 0
		}
	}
	return strings.Repeat("`", max(3, longest+1))
}

// indent nests text under a list item, so lines that start with "- "
// in a rewrite body never read as rows of their own.
func indent(text string) string {
